        OnlineStockSpan onlineStockSpan = new OnlineStockSpan();
        onlineStockSpan.next(5);
        int actualSpan = onlineStockSpan.next(7);
        int expectedSpan = 2;
        assertEquals(expectedSpan, actualSpan);
    }

